<script setup lang="ts">
import {computed,watch,onUnmounted,ref} from 'vue';import {useApplication} from '../../application';import UploadImportView from './UploadImportView.vue';import ImportDialogView from './ImportDialogView.vue';import MaterialImportSection from './MaterialImportSection.vue';import type {MaterialState} from './useMaterials';import {useImportDraft} from './useImportDraft';
const props=defineProps<{meetingId:string;newImport?:boolean;preparing?:boolean;preparationBusy?:boolean;preparationError?:string|null}>(),emit=defineEmits<{opened:[];closed:[];saved:[];discarded:[];processed:[];prepare:[];background:[kind:'local'|'library']}>(),{uploadQueue:queue,session,discovery,uploads,importDrafts,journals,pendingImports}=useApplication(),localError=ref<string|null>(null),closeAttempted=ref(false),materialVisible=ref(false),materialState=ref<MaterialState>({busy:false,blocked:false,failed:false,hasFiles:false,closeBlocked:false}),view=ref<InstanceType<typeof ImportDialogView>>();
const draft=useImportDraft(importDrafts,uploads,queue,()=>session.current.value?.actor.enterpriseId??null,()=>props.meetingId,journals,discovery.lookup,pendingImports);
const stop=watch(()=>[session.current.value?.actor.enterpriseId,props.meetingId],()=>{localError.value=null;if(session.current.value&&props.meetingId)void draft.open();else draft.invalidate(!session.current.value);},{immediate:true});
const running=computed(()=>queue.items.value.some(i=>['QUEUED','VERIFYING','INITIALIZING','ABORTING'].includes(i.status))),pending=computed(()=>['PREPARED','UNCERTAIN','DENIED'].includes(queue.importCommand.state.value)),acknowledged=computed(()=>queue.importCommand.state.value==='ACKNOWLEDGED');
const allReady=computed(()=>queue.items.value.length>0&&queue.items.value.every(i=>!!i.fileId));const closeBlocked=computed(()=>props.preparationBusy||draft.busy.value||running.value||queue.importBusy.value||pending.value||materialState.value.closeBlocked||queue.items.value.some(i=>!i.fileId&&!i.canRemove));
function deferClose(){
 if(draft.defer(!!props.newImport))return true;
 localError.value='暂时无法保存恢复记录，请重试。';
 return false;
}
const recoveringDiscard=computed(()=>draft.pending.value&&draft.command.snapshot.value?.operation==='IMPORT_DRAFT_DISCARD');
watch(closeBlocked,blocked=>{if(!blocked)closeAttempted.value=false;});
const closeNotice=computed(()=>closeAttempted.value&&closeBlocked.value?'文件上传或原请求结果尚未确认，请先完成上传或恢复原请求。':null);
const saveDisabled=computed(()=>props.preparing||!draft.saved.value||!!draft.error.value&&draft.rejected.value||!queue.ready.value||queue.blocked.value||!allReady.value||closeBlocked.value);
const startDisabled=computed(()=>props.preparing||draft.loading.value||draft.busy.value||draft.pending.value||!!draft.error.value||!queue.ready.value||queue.blocked.value||queue.importBusy.value||materialState.value.busy||materialState.value.blocked||(!pending.value&&!allReady.value)||['CONFLICT','REJECTED'].includes(queue.importCommand.state.value));
const reason=computed(()=>props.preparing?(props.preparationError?'会议准备未完成，请重试原请求。':'正在准备导入会议…'):draft.busy.value?(recoveringDiscard.value?'正在放弃导入…':'正在确认导入操作…'):draft.denied.value?'当前账号无法确认原导入操作。':draft.pending.value?(recoveringDiscard.value?'上次放弃导入的结果待确认，可重试或暂时关闭。':'上次保存导入的结果待确认，可重试或暂时关闭。'):acknowledged.value?'导入任务已受理，不表示处理已完成。':pending.value?'原导入结果尚未确认，请重试同一请求。':running.value?'请等待会议文件上传及校验完成':queue.items.value.some(i=>!i.fileId)?'有文件添加失败，请重试成功或移除':!queue.items.value.length?'请先添加可用的会议录音或转写文件':materialState.value.blocked?'正在确认背景材料状态': '背景材料和会议信息均可稍后补充。');
async function act(run:()=>Promise<unknown>|unknown){try{localError.value=null;await run();}catch(cause){localError.value=cause instanceof Error?cause.message:'操作未完成，请重试。';}}
let mounted=true;
async function submit(){const who=session.current.value?.actor.enterpriseId,id=props.meetingId;await act(async()=>{if(!pending.value&&!acknowledged.value)await draft.save();await queue.submitImport();});if(!mounted||session.current.value?.actor.enterpriseId!==who||props.meetingId!==id||queue.importCommand.snapshot.value?.actor!==who||queue.importCommand.snapshot.value?.resource!==id)return;if(queue.importCommand.state.value==='ACKNOWLEDGED'&&queue.importCommand.ack.value?.taskId){forceClose();emit('processed');}}
async function save(){if(draft.pending.value&&draft.command.snapshot.value?.operation==='IMPORT_DRAFT_DISCARD'){await discard();return;}if(!draft.pending.value&&saveDisabled.value)return;await act(async()=>{const result=await draft.save();if(!mounted||!result||result.meetingId!==props.meetingId)return;forceClose();emit('saved');});}
async function discard(){if(draft.busy.value||running.value||queue.importBusy.value||pending.value)return;await act(async()=>{const result=await draft.discard();if(!mounted||!result||result.meetingId!==props.meetingId)return;forceClose();emit('discarded');});}
watch(()=>[draft.loading.value,queue.items.value.map(f=>f.fileId??f.status).join(','),draft.saved.value?.revisionToken],()=>{if(!props.newImport&&!draft.loading.value&&draft.saved.value&&!draft.pending.value&&!draft.busy.value&&queue.importCommand.state.value==='EMPTY'&&allReady.value&&queue.items.value.map(f=>f.fileId).join(',')!==draft.saved.value.orderedFileIds.join(','))void act(draft.save);});
function resetMaterial(){materialVisible.value=false;materialState.value={busy:false,blocked:false,failed:false,hasFiles:false,closeBlocked:false};}
function opened(){materialVisible.value=true;emit('opened');}function closed(){resetMaterial();emit('closed');}
function showModal(){return view.value?.showModal()??false;}function close(){const result=view.value?.close()??false;if(result)resetMaterial();return result;}function forceClose(){view.value?.forceClose();resetMaterial();}
defineExpose({showModal,close,forceClose,get open(){return view.value?.open??false;}});onUnmounted(()=>{mounted=false;stop();draft.invalidate();});
</script>
<template><ImportDialogView ref="view" :reason="reason" :error="props.preparationError??localError??draft.error.value??queue.error.value??closeNotice" :save-disabled="draft.pending.value?!draft.retryable.value:saveDisabled" :save-label="draft.cleanupPending.value?'重试清理恢复记录':draft.pending.value&&draft.command.snapshot.value?.operation==='IMPORT_DRAFT_DISCARD'?'重试放弃导入':undefined" :discard-disabled="running||pending||draft.pending.value&&draft.command.snapshot.value?.operation!=='IMPORT_DRAFT_DISCARD'" :prompt-busy="draft.busy.value" :start-disabled="startDisabled" :close-blocked="closeBlocked" :defer-close="props.preparing?()=>!props.preparationBusy:draft.pending.value?deferClose:undefined" :has-files="queue.items.value.length>0" :new-import="newImport" :retrying="pending" :acknowledged="acknowledged" @opened="opened" @closed="closed" @save="save" @discard="discard" @submit="submit" @background="kind=>emit('background',kind)" @blocked-close="closeAttempted=true"><UploadImportView :items="props.preparing?[]:queue.items.value" :ready="!props.preparing&&queue.ready.value&&!draft.loading.value" :locked="draft.pending.value||draft.busy.value" :blocked="queue.blocked.value&&!draft.loading.value&&!draft.pending.value&&!!queue.error.value" :error="null" :import-state="queue.importCommand.state.value" :import-busy="queue.importBusy.value" :task-id="queue.importCommand.ack.value?.taskId??null" @add="files=>act(()=>queue.add(files))" @retry="(key,file)=>act(()=>queue.retry(key,file))" @discover="key=>act(()=>queue.discover(key,discovery.lookup))" @open="act(draft.open)" @submit="submit" @discard="act(queue.discardRejectedImport)" @remove="key=>act(()=>queue.remove(key))" @move="(key,direction)=>act(()=>queue.move(key,direction))" @abort="key=>act(()=>queue.abort(key))" @new-batch="act(queue.newBatch)"/><button v-if="queue.blocked.value&&queue.error.value&&!draft.pending.value&&!draft.loading.value" type="button" class="btn sm" @click="act(draft.open)">重新检查上传记录</button><template #materials><MaterialImportSection v-if="materialVisible&&props.meetingId" :meeting-id="props.meetingId" :locked="draft.pending.value||draft.busy.value" @state="materialState=$event"/><section v-else class="aci-import-section"><div class="ac-material-heading"><h3>会议背景材料及相关文档</h3><div class="flex wrap"><button class="btn" disabled>上传本地文件</button><button class="btn" disabled>从知识库选择</button></div></div><div class="small muted mb12">补充材料有助于更精准理解会议内容和生成纪要；未添加时，将基于会议录音或转写内容处理。</div><div data-aci-files="material"></div><div class="upload-zone ac-material-drop">可拖入背景材料，也可从知识库选择；无材料可直接开始处理。</div></section></template><button v-if="props.preparing&&props.preparationError" class="btn sm" :disabled="props.preparationBusy" @click="emit('prepare')">重试准备会议</button><div v-if="draft.error.value&&!draft.pending.value" class="ac-error small mt12"><button type="button" class="btn sm" @click="act(draft.open)">重新读取导入草稿</button></div></ImportDialogView></template>
